import {controller, target} from '@github/catalyst'
import {isFeatureEnabled} from '@github-ui/feature-flags'

const ANIMATION_DURATION = 200
const AT_COPILOT_VALUE = '@copilot'

const CHECKMARK_PATH =
  'M13.78 4.22a.75.75 0 010 1.06l-7.25 7.25a.75.75 0 01-1.06 0L2.22 9.28a.75.75 0 011.06-1.06L6 10.94l6.72-6.72a.75.75 0 011.06 0z'

const STYLES = {
  checkmarkContainer: 'width: 16px; flex-shrink: 0; display: flex; align-items: center; justify-content: center;',
  avatarIcon:
    'flex-shrink: 0; border-radius: 4px; box-shadow: 0 0 0 1px var(--borderColor-default, rgba(31,35,40,0.15)); display: inline-block; vertical-align: middle; overflow: hidden;',
} as const

type AnimationState = {visible: boolean; timer?: number}

export interface ModelOption {
  id: string
  name: string
  icon?: string
  multiplier?: number
  vendor?: string
  preview?: boolean
}

interface ModelsResponse {
  models: ModelOption[]
  current_model?: string
  token_based_billing_enabled?: boolean
}

interface AgentToken {
  token: string // e.g., "claude[agent]"
  /** Model-picker vendor, e.g., "anthropic". Empty/undefined for 3rd-party agents that don't participate in the model picker. */
  vendor?: string
  /** Stable agent slug, e.g. "anthropic-code-agent". Optional for 2-part token back-compat. */
  slug?: string
  mention: string // e.g., "@claude[agent]"
  /** Display name to show in the banner if an unauthorized mention is detected. */
  displayName?: string
  /** Server-precomputed status from the 5-part token; lets the banner skip mock fallback. */
  authorizationStatus?: 'authorized' | 'needs_authorization'
}

/**
 * Window events dispatched when an unauthorized-agent mention is detected/cleared.
 * Consumed by the React `agent-authorization-banner-partial` to render an inline banner.
 */
export type OpenAgentAuthorizationBannerEventDetail = {
  slug: string
  displayName: string
  avatarUrl?: string
  /** Server-precomputed status from the 5-part token; lets the banner skip mock fallback. */
  authorizationStatus?: 'authorized' | 'needs_authorization'
}

declare global {
  interface WindowEventMap {
    'open-agent-authorization-banner': CustomEvent<OpenAgentAuthorizationBannerEventDetail>
    'close-agent-authorization-banner': CustomEvent<void>
    'copilot-mention-quota-status': CustomEvent<{canStartSession: boolean}>
    'copilot-mention-detected': CustomEvent<{detected: boolean}>
    /**
     * Dispatched by late-mounting React components (e.g. `CopilotQuotaBannerPartial`) that
     * may have missed the most recent `copilot-mention-detected` event because they
     * mounted after the catalyst element already transitioned in/out of mention mode.
     * The catalyst element responds by re-emitting `copilot-mention-detected` with its
     * current state, making the handshake order-independent.
     */
    'copilot-mention-detected-request': CustomEvent<void>
  }
}

@controller('copilot-mentions-hint')
export class CopilotMentionsHintElement extends HTMLElement {
  @target declare inputField: HTMLInputElement | HTMLTextAreaElement
  @target declare indicator: HTMLElement
  @target declare infoText: HTMLElement
  @target declare button: HTMLButtonElement
  @target declare hintMessage: HTMLElement

  @target declare modelSelect: HTMLSelectElement
  @target declare modelAutocomplete: HTMLElement
  @target declare modelPickerBadge: HTMLButtonElement
  @target declare modelPickerIcon: HTMLElement
  @target declare modelPickerName: HTMLElement
  @target declare modelPickerMenu: HTMLElement

  @target declare quotaBanner: HTMLElement

  #animState: AnimationState = {visible: false}
  #selectedModel = 'auto'
  #models: ModelOption[] = []
  #modelsLoaded = false
  #modelsLoading = false
  // Captured lazily the first time we swap the primary submit button into
  // "Start new session" mode, so we can restore the button's original markup
  // (not just its text) on the way back out. Restoring via innerHTML preserves
  // rich submit buttons such as the PR review form's primary button, whose
  // ".add-comment-label" / ".start-review-label" spans are toggled by CSS.
  #originalSubmitHTML = ''
  // Whether the primary submit button is currently swapped to copilot mode.
  // Guards against clobbering the button when no swap is in effect.
  #submitTextSwapped = false
  #cachedCopilotIcon: SVGSVGElement | null = null
  #agentTokens: AgentToken[] = []
  // Tracks the vendor of the currently detected agent mention (null = @copilot)
  #currentVendor: string | null = null
  #tokenBasedBillingEnabled = false

  #abortController: AbortController | null = null

  // Tracks whether the viewer currently has insufficient agent quota
  // (`AgentQuotaSnapshot.can_start_session === false`). Reported by the
  // `copilot-quota-banner-partial` via the `copilot-mention-quota-status`
  // window event. Defaults to `true` so we don't accidentally disable
  // submission before the partial mounts.
  #canStartSession = true
  // Tracks whether the textarea currently contains an @copilot / agent mention,
  // so we can re-evaluate the submit button when the quota status changes.
  #inCopilotMode = false
  // Whether we have currently overridden the submit buttons to be disabled
  // because of insufficient quota — used to avoid stomping other disabled
  // states (e.g. empty input) when we release the override.
  #submitButtonsDisabledByQuota = false
  // All submit buttons in the textarea's enclosing form. Resolved once in
  // `connectedCallback` via a form-scoped query rather than catalyst's
  // descendant-only `@target`, because in the Rails-rendered comment form
  // the submit buttons (e.g. "Comment", "Close with comment", "Reopen and
  // comment") are rendered as siblings of `<copilot-mentions-hint>` rather
  // than descendants. A form-scoped lookup also catches every submit button
  // so the gate can't be bypassed via secondary buttons.
  #formSubmitButtons: HTMLButtonElement[] = []

  get #isModelPickerEnabled(): boolean {
    return (
      isFeatureEnabled('copilot_swe_agent_pr_comment_model_picker') && this.hasAttribute('data-model-picker-enabled')
    )
  }

  get #isTokenBasedBillingEnabled(): boolean {
    return this.#tokenBasedBillingEnabled || this.hasAttribute('data-token-based-billing-enabled')
  }

  get #escapedCopilotValue(): string {
    return AT_COPILOT_VALUE.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
  }

  connectedCallback() {
    if (!this.inputField) return

    this.#abortController = new AbortController()
    const {signal} = this.#abortController

    // Resolve every submit button in the textarea's enclosing form. The
    // `<copilot-mentions-hint>` element wraps only the textarea in Rails-
    // rendered comment forms, so catalyst's descendant-scoped `@target` can't
    // find the submit button(s). A form-scoped lookup also catches secondary
    // submit buttons like "Close with comment" and "Reopen and comment" so
    // they get the same quota gate.
    const enclosingForm = this.inputField.closest('form')
    this.#formSubmitButtons = enclosingForm
      ? Array.from(enclosingForm.querySelectorAll<HTMLButtonElement>('button[type="submit"]'))
      : []

    if (this.infoText) {
      this.#animState = {visible: !this.infoText.classList.contains('sr-only')}
    }

    this.#parseAgentTokens()

    const inputEvents = ['input', 'change', 'click', 'keyup', 'select'] as const
    for (const event of inputEvents) {
      this.inputField.addEventListener(event, this.#updateIndicator, {signal})
    }
    this.inputField.addEventListener('keydown', this.#handleKeyDown as EventListener, {signal})

    // Listen for text-expander-element commits so that mentions inserted via
    // autocomplete (e.g. @claude[agent]) are detected immediately. The
    // text-expander sets input.value directly without firing an 'input' event.
    const textExpander = this.inputField.closest('text-expander')
    textExpander?.addEventListener('text-expander-committed', this.#updateIndicator, {signal})

    this.button?.addEventListener('click', this.#toggleInfoText, {signal})

    const form = this.inputField.closest('form')
    form?.addEventListener('reset', this.#handleFormReset, {signal})
    form?.addEventListener('submit', this.#handleFormSubmit, {signal})

    // Listen for quota-status updates from `copilot-quota-banner-partial` so we
    // can disable the submit button when the viewer cannot start a new agent
    // session and currently has an @copilot / agent mention in the textarea.
    window.addEventListener('copilot-mention-quota-status', this.#handleQuotaStatus, {signal})

    // Late-mounting React partials (e.g. CopilotQuotaBannerPartial) may have
    // missed the most recent `copilot-mention-detected` event. They request
    // a re-emit on mount; we respond with the current `#inCopilotMode` state
    // so the handshake is order-independent. See `#dispatchMentionDetected`
    // and the matching `useEffect` in CopilotQuotaBannerPartial.tsx.
    window.addEventListener('copilot-mention-detected-request', this.#handleMentionDetectedRequest, {signal})

    if (this.#isModelPickerEnabled) {
      // Cache the server-rendered Primer octicon so we can reuse it
      // instead of hardcoding SVG paths that may drift out of sync.
      if (this.modelPickerIcon instanceof SVGSVGElement) {
        this.#cachedCopilotIcon = this.modelPickerIcon.cloneNode(true) as SVGSVGElement
      }
      this.modelSelect?.addEventListener('change', this.#handleModelChange, {signal})
      this.modelAutocomplete?.addEventListener('click', this.#handleDropdownClick, {signal})
      this.modelPickerMenu?.addEventListener('toggle', this.#handleMenuToggle, {signal})
    }

    this.button?.setAttribute('aria-expanded', 'false')
    this.#updateIndicator()
  }

  disconnectedCallback() {
    this.#abortController?.abort()
    this.#abortController = null

    if (this.#animState.timer) {
      clearTimeout(this.#animState.timer)
    }
  }

  #parseAgentTokens() {
    const tokensAttr = this.getAttribute('data-agent-mention-tokens')
    if (!tokensAttr) return

    this.#agentTokens = tokensAttr
      .split(',')
      .filter(Boolean)
      .reduce<AgentToken[]>((acc, entry) => {
        // Format: <token>:<vendor>[:<slug>[:<displayName>[:<authorizationStatus>]]]
        // - The displayName uses URI encoding so it can safely contain spaces.
        // - The vendor segment may be empty for 3rd-party agents that don't
        //   participate in the model-picker UX; those agents only need
        //   recognition for the authorization banner.
        // - The authorizationStatus is "authorized" | "needs_authorization" and
        //   is only present when Rails is on the
        //   `copilot_swe_agent_authorization_status` flag.
        const parts = entry.split(':')
        if (parts.length < 2) return acc
        const token = parts[0]
        if (!token) return acc
        const vendor = parts[1] || undefined
        const slug = parts[2] || undefined
        const displayName = parts[3] ? decodeURIComponent(parts[3]) : undefined
        const authorizationStatus =
          parts[4] === 'authorized' || parts[4] === 'needs_authorization' ? parts[4] : undefined
        acc.push({token, vendor, slug, displayName, authorizationStatus, mention: `@${token}`})
        return acc
      }, [])
  }

  #hasAgentTokenMention(text: string, agentMention: string): boolean {
    const escaped = agentMention.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
    const pattern = `(?:^|[^A-Za-z0-9])${escaped}(?:\\+[A-Za-z0-9._-]+)?(?:[^A-Za-z0-9+\\[]|$)`
    return new RegExp(pattern, 'i').test(text)
  }

  /** Detects whether the text contains a copilot or 3rd-party agent mention. */
  #detectMention(text: string): {found: boolean; vendor: string | null; agent: AgentToken | null} {
    if (this.#hasCopilotMention(text)) {
      return {found: true, vendor: null, agent: null}
    }

    for (const agent of this.#agentTokens) {
      if (this.#hasAgentTokenMention(text, agent.mention)) {
        return {found: true, vendor: agent.vendor ?? null, agent}
      }
    }

    return {found: false, vendor: null, agent: null}
  }

  #hasCopilotMention(text: string): boolean {
    const pattern = `(?:^|[^A-Za-z0-9])${this.#escapedCopilotValue}(?:\\+[A-Za-z0-9.-]+)?(?:[^A-Za-z0-9+]|$)`
    return new RegExp(pattern, 'i').test(text)
  }

  #isCaretInMention(text: string, caret: number): boolean {
    const re = new RegExp(`(?:^|[^a-zA-Z0-9])(${this.#escapedCopilotValue}(?:\\+[A-Za-z0-9.-]+)?\\s?)`, 'gi')

    for (let m: RegExpExecArray | null; (m = re.exec(text)); ) {
      const mention = m[1]
      if (!mention) continue
      const start = m.index + (m[0].length - mention.length)
      const end = start + mention.length
      if (caret >= start && caret <= end) return true
    }
    return false
  }

  #updateIndicator = () => {
    if (!this.inputField) return

    const text = this.inputField.value
    const {found, vendor, agent} = this.#detectMention(text)

    if (!found) {
      this.#handleNoCopilotMention()
      this.#dispatchAuthorizationBannerEvent(null)
      return
    }

    // When the detected vendor changes, re-fetch models for the new vendor
    if (vendor !== this.#currentVendor) {
      this.#currentVendor = vendor
      this.#modelsLoaded = false
      this.#models = []
      this.#selectedModel = 'auto'
    }

    this.#handleCopilotMentionPresent(text)
    this.#dispatchAuthorizationBannerEvent(agent)
  }

  /**
   * Dispatches a window event for the React `agent-authorization-banner` partial
   * to render or clear the inline banner. The partial double-checks the auth
   * state via the same mock client the pickers use, so this is safe to call
   * even when the feature flag is off — the partial will simply ignore opens
   * for agents that don't require authentication.
   *
   * When Rails embeds an `authorizationStatus` in the token (5-part format),
   * we forward it on the event so the partial can short-circuit its mock
   * fallback.
   */
  #dispatchAuthorizationBannerEvent(agent: AgentToken | null) {
    if (!agent || !agent.slug) {
      window.dispatchEvent(new CustomEvent('close-agent-authorization-banner'))
      return
    }

    window.dispatchEvent(
      new CustomEvent('open-agent-authorization-banner', {
        detail: {
          slug: agent.slug,
          displayName: agent.displayName ?? agent.token.replace('[agent]', ''),
          authorizationStatus: agent.authorizationStatus,
        },
      }),
    )
  }

  #handleNoCopilotMention() {
    const wasInCopilotMode = this.#inCopilotMode
    this.#inCopilotMode = false

    if (this.indicator) this.indicator.hidden = true

    if (this.infoText) {
      this.infoText.hidden = true
      this.infoText.classList.remove('sr-only')
    }
    this.#animState = {visible: false}

    if (this.button) {
      this.button.classList.remove('is-expanded')
      this.button.style.backgroundColor = ''
      this.button.setAttribute('aria-expanded', 'false')
    }

    this.#resetModelSelection()
    this.#hideModelPickerBadge()
    this.#hideQuotaBanner()
    this.#showHintMessage()
    this.#updateSubmitButton(false)
    this.#applySubmitButtonQuotaState()

    if (wasInCopilotMode) {
      this.#dispatchMentionDetected(false)
    }
  }

  #handleCopilotMentionPresent(text: string) {
    const wasInCopilotMode = this.#inCopilotMode
    this.#inCopilotMode = true
    this.#showQuotaBanner()

    if (this.#isModelPickerEnabled) {
      // Show the badge immediately for all agents. For vendor agents the
      // badge starts with the "Auto" label/icon and updates once models load.
      this.#showModelPickerBadge()
      this.#hideHintMessage()
      this.#updateSubmitButton(true)

      if (!this.#modelsLoaded && !this.#modelsLoading) {
        void this.#fetchModels()
      }
    }

    if (this.indicator) this.indicator.hidden = false

    if (this.infoText && !this.#isModelPickerEnabled) {
      this.infoText.hidden = false
    }

    if (this.infoText && this.button && !this.#isModelPickerEnabled) {
      const caret = this.inputField.selectionStart ?? 0
      const shouldShow = this.#isCaretInMention(text, caret)

      if (!shouldShow && !this.#animState.visible) {
        this.infoText.classList.add('sr-only')
      }

      this.#animateInfoText(shouldShow)
      this.button.classList.toggle('is-expanded', shouldShow)
      this.button.style.backgroundColor = shouldShow ? 'var(--bgColor-muted)' : ''
      this.button.setAttribute('aria-expanded', shouldShow ? 'true' : 'false')
    }

    this.#applySubmitButtonQuotaState()

    if (!wasInCopilotMode) {
      this.#dispatchMentionDetected(true)
    }
  }

  /**
   * Notify the `copilot-quota-banner-partial` React partial that the textarea
   * has entered or exited @copilot / agent-mention mode, so it can lazily
   * enable its quota-snapshot query (and disable it again when the mention is
   * cleared). This keeps the quota API call proportional to actual @copilot
   * usage instead of firing on every PR page load.
   *
   * The event is edge-triggered (only fires on transitions in/out of mention
   * mode). To handle late-mounting listeners that miss an edge, we also:
   *
   *   1. Reflect the current state to a `data-in-copilot-mode` attribute on
   *      this element so late-mounting code can read it synchronously from
   *      the DOM without needing an event.
   *   2. Re-emit on demand when a `copilot-mention-detected-request` event
   *      is dispatched (see `#handleMentionDetectedRequest`).
   *
   * Together these make the handshake order-independent.
   */
  #dispatchMentionDetected(detected: boolean) {
    this.toggleAttribute('data-in-copilot-mode', detected)
    window.dispatchEvent(new CustomEvent('copilot-mention-detected', {detail: {detected}}))
  }

  /**
   * Respond to a late-mounting React partial's request for the current
   * mention-mode state by re-emitting `copilot-mention-detected`. Idempotent
   * and safe to call at any time — multiple subscribers can request without
   * coordinating, and the same state value is just rebroadcast.
   */
  #handleMentionDetectedRequest = () => {
    window.dispatchEvent(new CustomEvent('copilot-mention-detected', {detail: {detected: this.#inCopilotMode}}))
  }

  #handleQuotaStatus = (event: CustomEvent<{canStartSession: boolean}>) => {
    this.#canStartSession = event.detail.canStartSession
    this.#applySubmitButtonQuotaState()
  }

  /**
   * Convenience accessor for the primary submit button — used by the
   * model-picker text swap. The primary button is the first form submit
   * button that doesn't carry a `name` attribute (which secondary buttons
   * like "Close with comment" use to differentiate the submission).
   */
  get #primarySubmitButton(): HTMLButtonElement | undefined {
    return this.#formSubmitButtons.find(btn => !btn.hasAttribute('name')) ?? this.#formSubmitButtons[0]
  }

  /**
   * Toggle every form submit button's disabled state based on whether the
   * viewer is currently composing an @copilot / agent mention AND has
   * insufficient quota to start a new session.
   *
   * SAFETY (two-layer gate, see CopilotQuotaBannerPartial.tsx for the other
   * layer): a `copilot-mention-quota-status` event with
   * `canStartSession: false` alone is NOT enough to disable any buttons —
   * `#inCopilotMode` must also be true. So if the partial misbehaves (e.g.
   * leaks a stale `canStartSession: false`), the buttons will still only
   * disable while an @copilot/agent mention is actively in the textarea.
   *
   * We are careful not to stomp disabled states owned by other code paths
   * (e.g. empty-textarea handling, in-flight submit guards, server-rendered
   * pre-disabled buttons):
   *
   *   - On apply: skip buttons that are already disabled by something else.
   *     They stay disabled regardless and tagging them as quota-disabled
   *     would cause us to release that other code's lock when our gate
   *     lifts.
   *   - On release: only re-enable buttons we explicitly tagged with
   *     `data-disabled-by-quota="true"`. Buttons disabled by another path
   *     keep their disabled state.
   */
  #applySubmitButtonQuotaState() {
    if (this.#formSubmitButtons.length === 0) return

    const shouldDisable = this.#inCopilotMode && !this.#canStartSession

    if (shouldDisable && !this.#submitButtonsDisabledByQuota) {
      for (const btn of this.#formSubmitButtons) {
        if (btn.disabled) continue
        btn.disabled = true
        btn.setAttribute('aria-disabled', 'true')
        btn.setAttribute('data-disabled-by-quota', 'true')
      }
      this.#submitButtonsDisabledByQuota = true
    } else if (!shouldDisable && this.#submitButtonsDisabledByQuota) {
      for (const btn of this.#formSubmitButtons) {
        if (btn.getAttribute('data-disabled-by-quota') !== 'true') continue
        btn.disabled = false
        btn.removeAttribute('aria-disabled')
        btn.removeAttribute('data-disabled-by-quota')
      }
      this.#submitButtonsDisabledByQuota = false
    }
  }

  #showHintMessage() {
    if (this.hintMessage) {
      this.hintMessage.hidden = false
    }
  }

  #hideHintMessage() {
    if (this.hintMessage) {
      this.hintMessage.hidden = true
    }
  }

  #showModelPickerBadge() {
    if (!this.modelPickerBadge) return

    this.modelPickerBadge.hidden = false
    this.#updateModelPickerBadgeDisplay()

    if (this.infoText) this.infoText.hidden = true
    if (this.button) this.button.hidden = true
  }

  #hideModelPickerBadge() {
    if (!this.modelPickerBadge) return

    this.modelPickerBadge.hidden = true
    if (this.button) this.button.hidden = false
  }

  #showQuotaBanner() {
    if (this.quotaBanner) this.quotaBanner.hidden = false
  }

  #hideQuotaBanner() {
    if (this.quotaBanner) this.quotaBanner.hidden = true
  }

  #sanitizeIconUrl(icon: string | null | undefined): string {
    if (!icon) return ''

    try {
      const url = new URL(icon, window.location.origin)
      if (url.protocol === 'http:' || url.protocol === 'https:') {
        return url.href
      }
    } catch {
      // Invalid URL
    }

    return ''
  }

  #updateModelPickerBadgeDisplay() {
    const model = this.#getSelectedModelInfo()
    const currentIcon = this.modelPickerIcon

    if (currentIcon) {
      const newIcon =
        model.id === 'auto' || !model.icon ? this.#getAutoModelIcon(16) : this.#createAvatarIcon(model.icon, 16)
      newIcon.setAttribute('data-target', 'copilot-mentions-hint.modelPickerIcon')
      currentIcon.replaceWith(newIcon)
    }

    if (this.modelPickerName) {
      this.modelPickerName.textContent = model.name
    }
  }

  #getSelectedModelInfo(): ModelOption {
    const model = this.#models.find(m => m.id === this.#selectedModel)
    if (model && model.id !== 'auto') return model

    const listContainer = this.modelAutocomplete
    const staticItem = listContainer?.querySelector(`[data-model-id="${this.#selectedModel}"]`)
    if (staticItem) {
      return {
        id: this.#selectedModel,
        name: staticItem.getAttribute('data-model-name') || this.#selectedModel,
        icon: this.#sanitizeIconUrl(staticItem.getAttribute('data-model-icon')),
      }
    }

    return {id: 'auto', name: 'Auto'}
  }

  #handleMenuToggle = (event: Event) => {
    const toggleEvent = event as ToggleEvent
    if (toggleEvent.newState === 'open') {
      if (!this.#modelsLoaded && !this.#modelsLoading) {
        void this.#fetchModels()
      }
      this.#renderModels()
    }
  }

  #updateSubmitButton(isCopilotMode: boolean) {
    const primary = this.#primarySubmitButton
    if (!primary) return

    if (isCopilotMode) {
      // Capture the original markup once, before the first swap, so we can
      // restore it verbatim later. Using innerHTML (not textContent) preserves
      // rich buttons like the PR review form's primary submit button.
      if (!this.#submitTextSwapped) {
        this.#originalSubmitHTML = primary.innerHTML
        this.#submitTextSwapped = true
      }
      primary.textContent = 'Start new session'
    } else if (this.#submitTextSwapped) {
      // eslint-disable-next-line @github-ui/github-monorepo/require-set-sanitized-inner-html -- re-assigns HTML previously read from the live DOM (string)
      primary.innerHTML = this.#originalSubmitHTML
      this.#submitTextSwapped = false
    }
  }

  async #fetchModels() {
    let modelsUrl = this.getAttribute('data-models-url') || this.modelAutocomplete?.getAttribute('data-models-url')

    if (!modelsUrl) {
      this.#modelsLoaded = true
      return
    }

    // Append vendor filter for 3rd-party agents
    if (this.#currentVendor) {
      const separator = modelsUrl.includes('?') ? '&' : '?'
      modelsUrl = `${modelsUrl}${separator}vendor=${encodeURIComponent(this.#currentVendor)}`
    }

    this.#modelsLoading = true

    try {
      const response = await fetch(modelsUrl, {
        headers: {
          Accept: 'application/json',
          'X-Requested-With': 'XMLHttpRequest',
        },
      })

      if (!response.ok) {
        throw new Error(`Failed to fetch models: ${response.status}`)
      }

      const data: ModelsResponse = await response.json()
      this.#models = this.#currentVendor ? this.#filterModelsByVendor(data.models) : data.models

      if (data.token_based_billing_enabled != null) {
        this.#tokenBasedBillingEnabled = data.token_based_billing_enabled
      }

      this.#renderModels()
      this.#modelsLoaded = true

      // Update the badge display now that models are loaded (may update icon/name
      // from "Auto" to the vendor-specific default).
      this.#updateModelPickerBadgeDisplay()
    } catch (error) {
      // eslint-disable-next-line no-console
      console.error('Failed to fetch cloud agent models:', error)
      this.#modelsLoaded = true
    } finally {
      this.#modelsLoading = false
    }
  }

  /**
   * Filters models by vendor when a 3rd-party agent is mentioned.
   * Uses the `vendor` field if present, falling back to the server-side
   * `?vendor=` query param for filtering.
   */
  #filterModelsByVendor(models: ModelOption[]): ModelOption[] {
    if (!this.#currentVendor) return models
    const vendorLower = this.#currentVendor.toLowerCase()
    const filtered = models.filter(m => m.vendor?.toLowerCase().includes(vendorLower))
    return filtered.length > 0 ? filtered : models
  }

  #renderModels() {
    const listContainer = this.modelAutocomplete
    if (!listContainer) return

    const actionList = listContainer.querySelector('ul[role="menu"]') || listContainer

    const existingItems = actionList.querySelectorAll('[role="menuitemradio"]')
    for (const item of existingItems) {
      item.remove()
    }

    const autoModel: ModelOption = {id: 'auto', name: 'Auto', multiplier: 1}
    const modelsToRender = [autoModel, ...this.#models.filter(m => m.id !== 'auto')]

    for (const model of modelsToRender) {
      actionList.appendChild(this.#createModelItem(model))
    }
  }

  #createModelItem(model: ModelOption): HTMLElement {
    const isSelected = model.id === this.#selectedModel
    const item = document.createElement('li')

    item.setAttribute('role', 'menuitemradio')
    item.setAttribute('data-model-id', model.id)
    item.setAttribute('data-model-name', model.name)
    item.setAttribute('tabindex', '-1')
    if (model.icon) item.setAttribute('data-model-icon', model.icon)
    item.setAttribute('aria-checked', isSelected ? 'true' : 'false')

    item.className = 'ActionListItem'
    item.style.cssText =
      'padding: 6px 10px; cursor: pointer; display: flex; align-items: center; gap: 8px; border-radius: 6px; font-size: 12px;'

    item.appendChild(this.#createCheckmark(isSelected))

    if (model.id === 'auto') {
      item.appendChild(this.#getAutoModelIcon(16))
    } else if (model.icon) {
      item.appendChild(this.#createAvatarIcon(model.icon, 16))
    }

    item.appendChild(this.#createModelLabel(model.name))

    if (model.preview) {
      const previewBadge = document.createElement('span')
      previewBadge.style.cssText =
        'font-size: 11px; padding: 1px 6px; color: var(--fgColor-muted); background: var(--bgColor-muted); border-radius: 999px; margin-left: auto;'
      previewBadge.textContent = 'Preview'
      item.appendChild(previewBadge)
    }

    if (model.multiplier !== undefined && !this.#isTokenBasedBillingEnabled) {
      const badge = document.createElement('span')
      badge.style.cssText =
        'font-size: 11px; padding: 1px 4px; color: var(--fgColor-muted); background: transparent; margin-left: auto;'
      badge.textContent = `${Number(model.multiplier.toFixed(2))}x`
      item.appendChild(badge)
    }

    item.addEventListener('keydown', (event: KeyboardEvent) => {
      // eslint-disable-next-line @github-ui/ui-commands/no-manual-shortcut-logic
      if (event.key === 'Enter' || event.key === ' ') {
        event.preventDefault()
        this.#selectModel(model.id)
      }
    })

    return item
  }

  #createCheckmark(isSelected: boolean): HTMLElement {
    const container = document.createElement('span')
    container.style.cssText = STYLES.checkmarkContainer

    if (isSelected) {
      const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg')
      svg.setAttribute('width', '16')
      svg.setAttribute('height', '16')
      svg.setAttribute('viewBox', '0 0 16 16')
      svg.setAttribute('fill', 'currentColor')
      svg.style.color = 'var(--fgColor-muted)'

      const path = document.createElementNS('http://www.w3.org/2000/svg', 'path')
      path.setAttribute('fill-rule', 'evenodd')
      path.setAttribute('d', CHECKMARK_PATH)
      svg.appendChild(path)
      container.appendChild(svg)
    }

    return container
  }

  /** Returns the vendor icon for auto model when a 3rd-party agent is mentioned, otherwise the Copilot octicon. */
  #getAutoModelIcon(size: number): HTMLElement | SVGSVGElement {
    if (this.#currentVendor) {
      const vendorModel = this.#models.find(m => m.icon)
      if (vendorModel?.icon) {
        return this.#createAvatarIcon(vendorModel.icon, size)
      }
      // Vendor context but models not loaded yet — return empty placeholder
      // to avoid briefly flashing the Copilot icon before vendor models load
      const placeholder = document.createElement('span')
      placeholder.style.cssText = `width: ${size}px; height: ${size}px; flex-shrink: 0; display: inline-block;`
      return placeholder
    }
    return this.#createCopilotOcticon(size)
  }

  #createCopilotOcticon(size: number): SVGSVGElement {
    if (this.#cachedCopilotIcon) {
      const clone = this.#cachedCopilotIcon.cloneNode(true) as SVGSVGElement
      clone.setAttribute('width', String(size))
      clone.setAttribute('height', String(size))
      clone.style.cssText = 'flex-shrink: 0;'
      return clone
    }

    // Fallback: create a minimal empty SVG if the server-rendered icon was not available
    const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg')
    svg.setAttribute('width', String(size))
    svg.setAttribute('height', String(size))
    svg.setAttribute('viewBox', '0 0 16 16')
    svg.setAttribute('fill', 'currentColor')
    svg.setAttribute('aria-hidden', 'true')
    svg.style.cssText = 'flex-shrink: 0;'
    return svg
  }

  #createAvatarIcon(iconUrl: string, size: number): HTMLElement {
    const icon = document.createElement('img')
    icon.src = this.#sanitizeIconUrl(iconUrl)
    icon.alt = ''
    icon.width = size
    icon.height = size
    icon.style.cssText = STYLES.avatarIcon
    return icon
  }

  #createModelLabel(name: string): HTMLElement {
    const label = document.createElement('span')
    label.className = 'ActionListItem-label'
    label.textContent = name
    return label
  }

  #resetModelSelection() {
    this.#selectedModel = 'auto'
    if (this.modelSelect) this.modelSelect.value = 'auto'
    this.#updateModelPickerBadgeDisplay()
  }

  #selectModel(modelId: string) {
    this.#selectedModel = modelId
    this.#renderModels()
    this.#updateModelPickerBadgeDisplay()
    if (this.modelSelect) this.modelSelect.value = modelId

    // Close the ActionMenu overlay
    const overlay = this.modelAutocomplete
    if (overlay && typeof overlay.hidePopover === 'function') {
      try {
        overlay.hidePopover()
      } catch (e) {
        if (!(e instanceof DOMException)) throw e
      }
    }

    this.inputField.focus()
  }

  #handleKeyDown = (_event: KeyboardEvent) => {}

  #handleDropdownClick = (event: Event) => {
    const eventTarget = event.target as HTMLElement
    const item = eventTarget.closest('[data-model-id]')
    if (item) {
      const modelId = item.getAttribute('data-model-id')
      if (modelId) {
        this.#selectModel(modelId)
      }
    }
  }

  #toggleInfoText = (event: Event) => {
    if (!this.button) return

    event.preventDefault()
    event.stopPropagation()

    const nextVisible = !this.#animState.visible
    this.#animateInfoText(nextVisible)
    this.button.classList.toggle('is-expanded', nextVisible)
    this.button.style.backgroundColor = nextVisible ? 'var(--bgColor-muted)' : ''
    this.button.setAttribute('aria-expanded', nextVisible ? 'true' : 'false')
  }

  #handleFormReset = () => {
    setTimeout(() => {
      this.#selectedModel = 'auto'
      if (this.modelSelect) {
        this.modelSelect.value = 'auto'
      }
      this.#updateIndicator()
    }, 0)
  }

  #animateInfoText(makeVisible: boolean) {
    if (!this.infoText) return
    if (this.#animState.visible === makeVisible) return

    if (this.#animState.timer) {
      clearTimeout(this.#animState.timer)
      this.#animState.timer = undefined
    }

    // Keep in layout during animations
    this.infoText.hidden = false

    if (makeVisible) {
      this.infoText.classList.remove('sr-only')

      this.infoText.style.transition = 'none'
      this.infoText.style.transform = 'translateX(-5px)'
      void this.infoText.offsetWidth // force reflow

      this.infoText.style.transition = `transform ${ANIMATION_DURATION}ms ease-out`
      this.infoText.style.transform = 'translateX(0)'

      this.#animState.visible = true
    } else {
      this.infoText.style.transition = `transform ${ANIMATION_DURATION}ms ease-in`
      this.infoText.style.transform = 'translateX(-5px)'

      this.#animState.visible = false
      this.#animState.timer = window.setTimeout(() => {
        if (!this.infoText) return
        this.infoText.classList.add('sr-only')
        this.#animState.timer = undefined
      }, ANIMATION_DURATION)
    }
  }

  // === Event Handlers ===
  #handleModelChange = (event: Event) => {
    const select = event.target as HTMLSelectElement
    this.#selectedModel = select.value
    this.#updateModelPickerBadgeDisplay()
  }

  #handleFormSubmit = () => {
    if (!this.inputField || !this.#isModelPickerEnabled) return
    if (this.#selectedModel === 'auto' || this.#selectedModel === '') return

    let text = this.inputField.value

    // Append model suffix to @copilot mentions
    const copilotPattern = new RegExp(
      `((?:^|[^A-Za-z0-9]))(${this.#escapedCopilotValue})(?![+])(?=[^A-Za-z0-9]|$)`,
      'gi',
    )
    text = text.replace(copilotPattern, `$1${AT_COPILOT_VALUE}+${this.#selectedModel}`)

    // Append model suffix to 3rd-party agent mentions
    for (const agent of this.#agentTokens) {
      const escapedMention = agent.mention.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
      const agentPattern = new RegExp(`((?:^|[^A-Za-z0-9]))(${escapedMention})(?![+])(?=[^A-Za-z0-9\\[]|$)`, 'gi')
      text = text.replace(agentPattern, `$1$2+${this.#selectedModel}`)
    }

    if (text !== this.inputField.value) {
      this.inputField.value = text
    }
  }
}
